"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["65260"],{13350(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>l,frontMatter:()=>a,contentTitle:()=>r,toc:()=>c,assets:()=>h});var s=JSON.parse('{"id":"tangfen/siwen","title":"","description":"Posting on forums isn\'t without common ground. One such principle is that you can\'t use the logic of \\"I don\'t care how things actually are, I just believe the facts are this way.\\" Of course, this kind of logic is a kind of logic -- everyone knows what kind of person loves to use it. Here, today we have another example.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/siwen.md","sourceDirName":"tangfen","slug":"/tangfen/siwen","permalink":"/en/tangfen/siwen","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"siwen","title":"","hide_table_of_contents":true,"sidebar_label":"[Siwen], I don\'t object to you displaying your absurd logic through your posts!"},"sidebar":"tangfenSidebar","previous":{"title":"Dushulang and others, please know your place!","permalink":"/en/tangfen/readingwolf"},"next":{"title":"\\"Labor\\" and \\"value\\" \u2014 can [Dushulang] and others not even understand the relationship between the two?","permalink":"/en/tangfen/workandvalues"}}'),i=t(74848),o=t(28453);let a={id:"siwen",title:"",hide_table_of_contents:!0,sidebar_label:"[Siwen], I don't object to you displaying your absurd logic through your posts!"},r="[Siwen], You Use Your Posts to Display Your Absurd Logic -- I Don't Object!",h={},c=[];function u(e){let n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"siwen-you-use-your-posts-to-display-your-absurd-logic----i-dont-object",children:"[Siwen], You Use Your Posts to Display Your Absurd Logic -- I Don't Object!"})}),"\n",(0,i.jsx)(n.p,{children:"Posting on forums isn't without common ground. One such principle is that you can't use the logic of \"I don't care how things actually are, I just believe the facts are this way.\" Of course, this kind of logic is a kind of logic -- everyone knows what kind of person loves to use it. Here, today we have another example."}),"\n",(0,i.jsx)(n.p,{children:"[Siwen] today, in \"The entire meaning of Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's post revolves around the verification of those underpants -- still talking about Gao Tianhu 'suspected of perjury' -- Reply to Tangfen,\" demonstrated a live-action version of this logic. See:"}),"\n",(0,i.jsx)(n.p,{children:"\"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's post, of course, is saying Gao Tianhu 'is suspected of perjury.' No matter how Tangfen defends her, it's useless, because the original intention of that post is exactly this. Tangfen repeatedly quotes those few sentences from Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n, saying: 'You can clearly see that Miss Chan's \"legal procedure\" here refers to going through legal procedures to verify whether \"the underpants bearing Gao Tianhu's own semen stain\" conform.' This is saying Gao Tianhu 'is suspected of perjury.' Because we are discussing a criminal matter, the 'legal procedure' here refers to the procedure prescribed by the Criminal Law; the 'verification' here refers to the 'appraisal' required by the Criminal Law to examine criminal evidence; and the goal of determining whether 'the underpants with semen stain' 'conform' is to establish the evidence as required by Criminal Law.\""}),"\n",(0,i.jsx)(n.p,{children:'In the above passage, [Siwen]\'s bet-like string of emphatic "refers to" constructions reveal logic like this: because I [Siwen] believe Miss Chan believes Gao Tianhu "is suspected of perjury," therefore Miss Chan also believes Gao Tianhu "is suspected of perjury," and therefore when Miss Chan says verification should be done, it means verification according to criminal procedures. And because Miss Chan says those underpants should be verified, therefore Miss Chan is demanding criminal verification, therefore Miss Chan must believe Gao Tianhu "is suspected of perjury."'}),"\n",(0,i.jsx)(n.p,{children:'The confusion in the above logic should be clear to everyone. But the realistic logic is: whatever [Siwen] believes has nothing to do with Miss Chan. Whatever he says Miss Chan "refers to" is just what he himself thinks, and has nothing to do with Miss Chan. Verifying evidence through legal procedures is not exclusively for criminal cases -- this is the most basic common sense. Moreover, Miss Chan specifically emphasized in her post: "Therefore, finding an authoritative institution or even a non-governmental organization to confirm this fact is the best method of verification." Excuse me, does this sound like the attitude toward a criminal case?'}),"\n",(0,i.jsx)(n.p,{children:'This [Siwen], responding three days later to my post with such a logically confused answer -- what this shows, everyone can comment on. But under no circumstances can one use the absurd logic of "I don\'t care how things actually are, I just believe the facts are this way" to discuss issues -- unless certain people feel this is the way to demonstrate their own realistic logic!'})]})}function l(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var s=t(96540);let i={},o=s.createContext(i);function a(e){let n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);